"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[22975],{69931:e=>{e.exports=JSON.parse('{"functions":[{"name":"init","desc":"Sets the shot-FX function (the controller\'s fold + flash + tracer + sound).","params":[{"name":"draw","desc":"","lua_type":"DrawShot"}],"returns":[],"function_type":"static","source":{"line":85,"path":"src/StarterPlayer/StarterPlayerScripts/AutoCannonController/Gunner.luau"}},{"name":"SetTrigger","desc":"The single trigger path: mouse input and the HUD\'s touch fire button\\n(`Signals.TurretTrigger`).","params":[{"name":"down","desc":"","lua_type":"boolean"}],"returns":[],"function_type":"static","source":{"line":94,"path":"src/StarterPlayer/StarterPlayerScripts/AutoCannonController/Gunner.luau"}},{"name":"attach","desc":"Adds the mount prompt to a placed turret (`promptPart` is its\\n`MountPromptPart`). Everything it makes goes into `cleaner`.","params":[{"name":"model","desc":"","lua_type":"Model"},{"name":"promptPart","desc":"","lua_type":"BasePart"},{"name":"cleaner","desc":"","lua_type":"Janitor.Janitor"}],"returns":[],"function_type":"static","source":{"line":233,"path":"src/StarterPlayer/StarterPlayerScripts/AutoCannonController/Gunner.luau"}},{"name":"Step","desc":"Per frame, before the rigs update: aim, report, predict shots.","params":[{"name":"dt","desc":"","lua_type":"number"}],"returns":[],"function_type":"static","source":{"line":267,"path":"src/StarterPlayer/StarterPlayerScripts/AutoCannonController/Gunner.luau"}}],"properties":[],"types":[],"name":"Gunner","desc":"The local player\'s AutoCannon controls. `attach` puts a \\"Man AutoCannon\\"\\nProximityPrompt on a placed turret\'s `MountPromptPart`, plus the Stash (hold\\nF) and Move (hold G) prompts from `PlaceableActions.addPrompts`. All three\\nhide while anyone mans the turret or the local player mans any turret.\\nTriggering mount sends `ReqMountAutoCannon(model)`; the server seats\\nthe player and its answer plus `GunnerUserId` are the source of truth.\\n\\nWhile mounted: the CameraController aim mode keeps the mouse locked to the\\ncentre and shows the reticle; each frame (`Step`) the camera-centre ray gives\\nthe aim point, the local yaw/pitch turn toward it at `YawSpeed`/`PitchSpeed`\\nand drive the local `TurretRig` (`External = true`), `ReqAutoCannonAim` goes\\nout at `AimReportHz`, and while the trigger is held the shots are predicted\\nlocally (fold + flash + tracer + sound) at `FireRate` while seated, `Ammo > 0`\\nand not `Reloading`. MouseButton1 -> `SetTrigger`, R -> reload, X -> leave.\\n\\nLeaving (X, death, turret removed, or `GunnerUserId` no longer the local\\nplayer, which covers a jump-off and a failed sit) restores the camera and\\nthe mouse and fires `Signals.OnTurretMounted(nil)`.","realm":["Client"],"source":{"line":25,"path":"src/StarterPlayer/StarterPlayerScripts/AutoCannonController/Gunner.luau"}}')}}]);